#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.131193155, -0.371129495, 0.0035348400000000044], 'basis': [[-0.5527268509918498, 0.05607812933140577, 0.8314735543619675], [0.0, 0.9977333648336426, -0.06729140136553563], [-0.8333624830724224, -0.03719376437560117, -0.5514740208740017]], 'axis': [0.8314735543619675, -0.06729140136553563, -0.5514740208740017], 'zmin': -0.04440532415164491, 'zmax': 0.051403504422010735, 'profiles': [{'outer': [[-0.10488040966686774, -0.04803416730239644], [-0.10451258341315924, -0.04546400382700449], [-0.10376970547810159, -0.04195001173545654], [-0.10258832178783521, -0.03731731293802831], [-0.10088336576277673, -0.03174029413092076], [-0.09866200440974886, -0.025501249420041044], [-0.09588887059799132, -0.018880554041981346], [-0.09255681338982216, -0.012130393392050619], [-0.08858103408994283, -0.005558394623630702], [-0.08320380337419034, 0.0014839404047358572], [-0.07803471404738614, 0.006568745382973339], [-0.07165166845488283, 0.011088634255005678], [-0.06364742033808855, 0.014984245027020395], [-0.05395334767728642, 0.017836506770104645], [-0.04227214454043282, 0.019209223238828885], [-0.03009712716675987, 0.018748127607548907], [-0.01789936976943042, 0.017564571185478696], [-0.006402321126301525, 0.016919578058175438], [0.0026974907534669805, 0.0184189267985572], [0.005033525273600092, 0.02037921176778234], [0.00821549209885277, 0.023318614526094867], [0.00933642107262118, 0.026140065515287195], [0.010739841124100353, 0.030044471903271645], [0.011606382991315261, 0.03656068265278295], [0.011754931451989028, 0.042999359928770346], [0.011776190528932204, 0.04793706349889551], [0.01205207820419727, 0.051423328985997704], [0.012177387453382068, 0.05234464919398737], [0.012924315285318158, 0.0545021301924387], [0.014301772903438627, 0.05576940922801482], [0.014674902990365071, 0.055990698659853365], [0.016475658449258634, 0.05659483485769836], [0.019485215627805707, 0.05709097069497844], [0.023207657384549035, 0.05728832361998078], [0.05778722477326809, 0.05735088026048419], [0.06690475400795262, 0.057176711109297014], [0.07503741494345326, 0.05670212201621381], [0.08122543249043085, 0.05589157714845738], [0.08499106271591765, 0.054633382189224186], [0.08659478786435984, 0.053873795643728815], [0.08874546138226261, 0.05156345650577067], [0.08953774307462767, 0.04807748512518903], [0.08965097669998166, 0.04314159373949705], [0.08974292913931844, 0.020773236438988606], [0.0898561489037791, 0.012554612902498298], [0.09005416761987066, 0.004740791023109507], [0.09045021891294712, -0.0026673957596747375], [0.09115010687363526, -0.00977926775435079], [0.09230243532073804, -0.016696183322339398], [0.09394946566383817, -0.023498799135372783], [0.09585092891724258, -0.02992689195203443], [0.09926495464143617, -0.040487426687761625], [0.10023336171350403, -0.04409616682481364], [0.10074934207460638, -0.046703793223187046], [0.10094021291570474, -0.04864172731700655], [0.10097554986009855, -0.050194452877257816], [0.10081289861654379, -0.051567612617449736], [0.0998084841997809, -0.05278654794372699], [0.09803413672985765, -0.05405903983610096], [0.09556248878730417, -0.05490572267648141], [0.09096367433717752, -0.05583274324315563], [0.08873085523015302, -0.05609405655060576], [0.08281043025230347, -0.056612829409226025], [0.07414312066877474, -0.0569164362599721], [0.0654485596126341, -0.056812395971473736], [0.05944513613043992, -0.05646848251888939], [0.05243412496055118, -0.05555678258254531], [0.04956619177748897, -0.05480178926432838], [0.04747710237694355, -0.053899190249185984], [0.04491543352475064, -0.05303425597178611], [0.042424687745015933, -0.052664656051114485], [0.03731228938135393, -0.05247664962604788], [0.03286847164990647, -0.05266911577610672], [0.029478510779594028, -0.05323602483590256], [0.02805305429728093, -0.0539231373923505], [0.02693088734415876, -0.05486752984739575], [0.025880279927193203, -0.05563547841878753], [0.02485103555014848, -0.056287454485084265], [0.024101505873657898, -0.05661234437904141], [0.022304327406418897, -0.05700249500454045], [0.01871870142859368, -0.05733172355493976], [0.013084812751466007, -0.057469257190510825], [0.005160571349188176, -0.057535304875897385], [-0.04558784323692465, -0.057736688512730845], [-0.06033798123353211, -0.05773937806903589], [-0.07392533521012953, -0.057642039051786664], [-0.08482766262686757, -0.05732722076604761], [-0.09150492828296078, -0.056934260321493756], [-0.09897080479616549, -0.05592929342831066], [-0.10157024939599098, -0.05508110217382601], [-0.10384759110452477, -0.054089872064336], [-0.10490166874381089, -0.0528701320013095], [-0.10505024484082723, -0.0514964245214056], [-0.10502898576388404, -0.04996862438560412]], 'holes': []}], 'simplify_tolerance': 4.120515894018516e-05, 'sketch_entity_count': 94}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
